on conflict(disease_id) do nothing;

do $$
declare n integer; broken integer;
begin
 select count(*) into n from public.disease_mondo_orpha_review_queue;
 if n<>75 then raise exception 'Expected 75 pending MONDO source matches, got %',n;end if;
 select count(*) into broken from public.disease_mondo_orpha_review_queue r
 join public.disease_orpha_evidence_staging s on s.disease_id=r.disease_id and s.orpha_code=r.orpha_code;
 if broken<>75 then raise exception 'Source packet staging incomplete: %/75',broken;end if;
 if exists (select 1 from public.disease_mondo_orpha_review_queue r
 join public.disease_orpha_mappings m on m.orpha_code=r.orpha_code and m.disease_id<>r.disease_id)
 then raise exception 'Cross-source ORPHAcode conflicts with already published disease map';end if;
end $$;
